def transform(grid):
    H, W = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=lambda v: counts[v])
    out = [row[:] for row in grid]
    for r in range(H):
        for c in range(1, W - 1):
            v = grid[r][c]
            if v == bg and grid[r][c-1] != bg and grid[r][c+1] != bg:
                out[r][c] = 2
    return out
